{"cards": [{"node_code": "N_9c809203afe730fb", "definition": "研究航空运输企业（航空公司、机场等）的组织架构、管理模式、人力资源配置及内部运营效率的通用理论，旨在优化企业整体经营绩效。", "boundary": "本节点聚焦于企业内部的组织与管理机制，如部门设置、流程优化、绩效考核及战略管理。边界在于区分“内部管理”与“外部市场”（市场供需、定价策略归入市场营销或定价节点）及“具体国别制度”（特定国家的行政体制归入国别节点）。若内容涉及具体的财务核算方法，需视是否属于通用管理理论。", "includes": ["航空公司组织架构设计与职能分工理论", "航空企业人力资源管理与绩效考核体系", "企业内部运营流程优化与成本控制管理理论"], "excludes": ["航空运输市场宏观分析与需求预测", "特定国家航空行政管理体系与政策法规", "航空器工程技术及飞行操作规范"], "sibling_distinctions": [{"other_code": "N_5289c021e39854dd", "rule": "本节点侧重企业内部组织与管理机制；市场营销侧重外部客户需求挖掘、品牌策略及销售渠道管理。"}, {"other_code": "N_01adb5e4e61607ad", "rule": "本节点侧重管理流程与组织效率；定价与成本理论侧重具体的经济模型、运价制定及利润计算逻辑。"}], "cross_boundary_rule": "涉及航空企业战略时，若侧重内部资源调配与组织变革，归入本节点；若侧重市场定位与竞争策略，需结合市场营销节点判断，通常战略管理归入本节点。"}, {"node_code": "N_a8407dda1ad2eff2", "definition": "研究专业飞行活动（如公务机、通用航空、特种飞行）的经济特征、运营模式及资源配置理论，区别于大规模商业客运。", "boundary": "本节点聚焦于非大规模商业客运的专业飞行领域，包括公务航空、包机、农业航空、救援等。边界在于区分“专业飞行”与“商业航空”（大规模定期客运归入其他节点）及“纯飞行技术”（飞行原理、操纵技术归入工程技术节点）。若内容涉及专业飞行的经济成本、市场供需或运营效率，归入本节点。", "includes": ["公务航空与通用航空的经济运营模式", "特种飞行（救援、测绘等）的成本效益分析", "专业飞行市场的供需特征与定价机制"], "excludes": ["大规模商业定期客运的运营理论", "飞行驾驶操作技术与航空器机械原理", "特定国家通用航空政策法规的具体条文"], "sibling_distinctions": [{"other_code": "N_9ae23662c114bf6f", "rule": "本节点侧重特定类型（专业/通用）飞行的经济理论；运输业务侧重航空运输整体业务流程（如客货运输、地面服务）的通用理论。"}, {"other_code": "N_9c809203afe730fb", "rule": "本节点侧重专业飞行领域的特定经济规律；企业组织管理侧重所有航空企业通用的内部组织与管理理论。"}], "cross_boundary_rule": "涉及通用航空时，若侧重其经济属性、市场分析及运营效率，归入本节点；若侧重空域管理、适航标准或具体飞行操作，需视树中是否有相关技术或法规节点，若无则保留在本节点作为背景。"}, {"node_code": "N_9ae23662c114bf6f", "definition": "研究航空运输核心业务流程（如旅客运输、货物运输、行李处理）的通用理论、服务标准及运营效率优化方法。", "boundary": "本节点聚焦于航空运输“业务”层面的通用理论，包括客货运输流程、地面服务标准、中转衔接及业务量统计。边界在于区分“业务流程”与“企业管理”（组织架构归入企业组织节点）及“市场营销”（销售策略归入市场营销节点）。若内容涉及具体的业务操作规范、服务流程设计或业务量分析模型，归入本节点。", "includes": ["旅客与货物运输业务流程及操作规范理论", "航空地面服务标准与中转衔接效率分析", "航空运输业务量统计、分析及服务流程优化"], "excludes": ["航空公司内部组织架构与人力资源理论", "航空运输市场宏观分析与需求预测模型", "航空器工程技术及飞行驾驶操作技术"], "sibling_distinctions": [{"other_code": "N_9c809203afe730fb", "rule": "本节点侧重具体运输业务的操作流程与服务标准；企业组织管理侧重内部部门设置、人员管理及战略决策。"}, {"other_code": "N_5289c021e39854dd", "rule": "本节点侧重运输业务执行过程与服务交付；市场营销侧重产品推广、客户获取及销售渠道管理。"}], "cross_boundary_rule": "涉及航空服务时，若侧重服务流程设计、操作规范及业务效率，归入本节点；若侧重服务品牌塑造、客户满意度调查或销售策略，归入市场营销节点。"}]}
